    ["笔记本"] = "Блокнот",
    ["笔记的封皮完全由深黑色硬纸制成，散发出古\n老悠远的气息，丝毫没有变软和腐烂的迹象。"] = "Обложка тетради полностью сделана из тёмно-чёрной плотной бумаги и источает древнее,\nдалёкое дыхание эпох; на ней нет ни малейших признаков размягчения или гниения.",
    ["笔记的封皮完全由深黑色硬纸制成，散发出古\n老悠远的气息，丝毫没有变软和腐烂的迹象。\n\n一阵剧烈的头痛骤然袭来，仿佛是来自记忆深\n处的危险警示，阻止你翻开这本笔记。\n\n从笔记中抽出的纸牌，牌面上是一轮绯红满月，散发着诡异的月光。"] = "Обложка тетради целиком сделана из тёмно-чёрной плотной бумаги, от которой веет древностью. На ней нет ни малейших признаков обветшания или гниения.\n\nВнезапно накатывает острая головная боль — словно предупреждение об опасности из самых глубин памяти, не позволяющее открыть эту тетрадь.\n\nНа вынутой из тетради карте красуется алая полная луна, источающая зловещее лунное сияние.",
    ["笔记的封皮完全由深黑色硬纸制成，散发出古\n老悠远的气息，丝毫没有变软和腐烂的迹象。\n\n一阵剧烈的头痛骤然袭来，仿佛是来自记忆深\n处的危险警示，阻止你翻开这本笔记。\n\n你发现书页中好像夹着什么。"] = "Обложка тетради полностью сделана из тёмно-чёрной плотной бумаги и источает древнее,\nдалёкое дыхание эпох; на ней нет ни малейших признаков размягчения или гниения.\n\nВнезапно накатывает острая головная боль — словно опасное предостережение\nиз глубин памяти, не позволяющее открыть эту тетрадь.\n\nВы замечаете, что между страниц что-то вложено.",
    ["笔记的封皮完全由深黑色硬纸制成，散发出古\n老悠远的气息，丝毫没有变软和腐烂的迹象。\n\n书页中夹着的红月牌已经被取走。"] = "Обложка блокнота целиком изготовлена из темно-черной твердой бумаги, излучающей атмосферу старины и далекости без каких-либо признаков размягчения и разложения. \n\nМемориальную доску с красной луной, зажатую на страницах книги, убрали.",
    ["第一个水晶球的谜题：\n<InvHighlight>α乘以β</>等于<InvHighlight>12</>"] = "Загадка первого хрустального шара:\n<InvHighlight>α, умноженное на β</>, равно <InvHighlight>12</>",
    ["第一个水晶球的谜题：\n<InvHighlight>α乘以β</>等于<InvHighlight>12</>\n\n第二个水晶球的谜题：\n水晶球的位置<InvHighlight>(β减2,α减2)</>为<InvHighlight>(1,2)</>"] = "Загадка первого хрустального шара:\n<InvHighlight>α умножить на β</> равно <InvHighlight>12</>\n\nЗагадка второго хрустального шара:\nПозиция хрустального шара <InvHighlight>(β минус 2, α минус 2)</> равна <InvHighlight>(1,2)</>",
    ["第一个水晶球的谜题：\n<InvHighlight>α乘以β</>等于<InvHighlight>12</>\n\n第二个水晶球的谜题：\n水晶球的位置<InvHighlight>(β减2,α减2)</>为<InvHighlight>(1,2)</>\n\n第三个水晶球的谜题：\n水晶球的位置<InvHighlight>(α,ω加1)</>为<InvHighlight>(4,3)</>"] = "Загадка первого хрустального шара:\n<InvHighlight>α умножить на β</> равно <InvHighlight>12</>\n\nЗагадка второго хрустального шара:\nПозиция хрустального шара <InvHighlight>(β минус 2, α минус 2)</> равна <InvHighlight>(1,2)</>\n\nЗагадка третьего хрустального шара:\nПозиция хрустального шара <InvHighlight>(α, ω плюс 1)</> равна <InvHighlight>(4,3)</>",
    ["第一个水晶球的谜题：\n<InvHighlight>α乘以β</>等于<InvHighlight>12</>\n\n第二个水晶球的谜题：\n水晶球的位置<InvHighlight>(β减2,α减2)</>为<InvHighlight>(1,2)</>\n\n第三个水晶球的谜题：\n水晶球的位置<InvHighlight>(α,ω加1)</>为<InvHighlight>(4,3)</>\n\n第一个传送门：\n<InvHighlight>α加α</>等于<InvHighlight>8</>"] = "Загадка первого хрустального шара:\n<InvHighlight>α умножить на β</> равно <InvHighlight>12</>\n\nЗагадка второго хрустального шара:\nПозиция хрустального шара <InvHighlight>(β минус 2, α минус 2)</> равна <InvHighlight>(1,2)</>\n\nЗагадка третьего хрустального шара:\nПозиция хрустального шара <InvHighlight>(α, ω плюс 1)</> равна <InvHighlight>(4,3)</>\n\nПервый портал:\n<InvHighlight>α плюс α</> равно <InvHighlight>8</>",
    ["第一个水晶球的谜题：\n<InvHighlight>α乘以β</>等于<InvHighlight>12</>\n\n第二个水晶球的谜题：\n水晶球的位置<InvHighlight>(β减2,α减2)</>为<InvHighlight>(1,2)</>\n\n第三个水晶球的谜题：\n水晶球的位置<InvHighlight>(α,ω加1)</>为<InvHighlight>(4,3)</>\n\n第一个传送门：\n<InvHighlight>α加α</>等于<InvHighlight>8</>\n\n第二个传送门：\n<InvHighlight>β减α</>等于<InvHighlight>-1</>"] = "Загадка первого хрустального шара:\n<InvHighlight>α умножить на β</> равно <InvHighlight>12</>\n\nЗагадка второго хрустального шара:\nПозиция хрустального шара <InvHighlight>(β минус 2, α минус 2)</> равна <InvHighlight>(1,2)</>\n\nЗагадка третьего хрустального шара:\nПозиция хрустального шара <InvHighlight>(α, ω плюс 1)</> равна <InvHighlight>(4,3)</>\n\nПервый портал:\n<InvHighlight>α плюс α</> равно <InvHighlight>8</>\n\nВторой портал:\n<InvHighlight>β минус α</> равно <InvHighlight>-1</>",
    ["第一个水晶球的谜题：\n<InvHighlight>α乘以β</>等于<InvHighlight>12</>\n\n第二个水晶球的谜题：\n水晶球的位置<InvHighlight>(β减2,α减2)</>为<InvHighlight>(1,2)</>\n\n第三个水晶球的谜题：\n水晶球的位置<InvHighlight>(α,ω加1)</>为<InvHighlight>(4,3)</>\n\n第一个传送门：\n<InvHighlight>α加α</>等于<InvHighlight>8</>\n\n第二个传送门：\n<InvHighlight>β减α</>等于<InvHighlight>-1</>\n\n第三个传送门：\n<InvHighlight>α乘以β乘以ω</>等于<InvHighlight>24</>"] = "Загадка первого хрустального шара:\n<InvHighlight>α умножить на β</> равно <InvHighlight>12</>\n\nЗагадка второго хрустального шара:\nПозиция хрустального шара <InvHighlight>(β минус 2, α минус 2)</> — <InvHighlight>(1,2)</>\n\nЗагадка третьего хрустального шара:\nПозиция хрустального шара <InvHighlight>(α, ω плюс 1)</> — <InvHighlight>(4,3)</>\n\nПервый портал:\n<InvHighlight>α плюс α</> равно <InvHighlight>8</>\n\nВторой портал:\n<InvHighlight>β минус α</> равно <InvHighlight>-1</>\n\nТретий портал:\n<InvHighlight>α умножить на β умножить на ω</> равно <InvHighlight>24</>",
